class Solution:
    def convertToTitle(self, columnNumber: int) -> str:
        ans = []
        while columnNumber > 0:
            columnNumber -= 1
            ans.append(chr(65 + columnNumber % 26))
            columnNumber //= 26
        ans.reverse()
        return ''.join(ans)

